PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS source_instances(id TEXT PRIMARY KEY, root TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_files(id INTEGER PRIMARY KEY,path TEXT UNIQUE NOT NULL,fingerprint TEXT NOT NULL,generation INTEGER NOT NULL DEFAULT 0,offset INTEGER NOT NULL DEFAULT 0,last_start INTEGER NOT NULL DEFAULT 0,last_hash TEXT NOT NULL DEFAULT '',context TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS ingested_records(file_id INTEGER NOT NULL,generation INTEGER NOT NULL,offset INTEGER NOT NULL,kind TEXT NOT NULL,digest TEXT NOT NULL,PRIMARY KEY(file_id,generation,offset));
CREATE TABLE IF NOT EXISTS usage_responses(id TEXT PRIMARY KEY,source_id TEXT NOT NULL,thread_id TEXT NOT NULL,response_id TEXT NOT NULL,turn_id TEXT,event_time TEXT NOT NULL,digest TEXT NOT NULL,data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS usage_time ON usage_responses(event_time);
CREATE INDEX IF NOT EXISTS usage_thread ON usage_responses(thread_id);
CREATE TABLE IF NOT EXISTS legacy_usage_segments(id TEXT PRIMARY KEY,source_id TEXT NOT NULL,thread_id TEXT NOT NULL,turn_id TEXT,event_time TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS turns(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL,turn_id TEXT NOT NULL,event_time TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS items(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL,turn_id TEXT,event_time TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS thread_metadata(id TEXT PRIMARY KEY,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS identity_conflicts(id TEXT PRIMARY KEY,kind TEXT NOT NULL,event_time TEXT NOT NULL,details TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ingestion_issues(id TEXT PRIMARY KEY,kind TEXT NOT NULL,file TEXT,event_time TEXT NOT NULL,digest TEXT,message TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS budgets(id TEXT PRIMARY KEY,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inbox_events(id TEXT PRIMARY KEY,thread_id TEXT,turn_id TEXT,event_time TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS account_snapshots(id INTEGER PRIMARY KEY,collected_at TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS account_usage_snapshots(id INTEGER PRIMARY KEY,collected_at TEXT NOT NULL,data TEXT NOT NULL);
PRAGMA user_version=1;
